import * as React from 'react'
import EfStyleSheet from '../utils/style-helper'
import { Days } from '../library/enum-lists/calendar.enum-list';
import {} from 'date-fns';

interface Props {
    renderView: React.FC<{ style: React.CSSProperties, children: React.ReactNode }>,
    renderText: React.FC<{ style: React.CSSProperties, children: React.ReactNode }>,
    startDay?: number,
}

export const MonthCalendar = React.memo(({ renderView, startDay = 1, renderText }: Props) => {
    const View = React.useMemo(() => renderView, [renderView]);
    const Text = React.useMemo(() => renderText, [renderText]);
    return (
        <View style={styles.container}>
            <View style={styles.calendarContainer}>
                {
                    Array.from({ length: 7 }).map((_, index) => {
                        const dayIndex = (startDay + index) % 7;
                        return <View style={styles.item} key={index + 'day'}>
                            <Text style={{ fontWeight: 'bold' }}>{Days[dayIndex].sortLabel}</Text>
                        </View>
                    })
                }
            </View>
            <View style={styles.calendarContainer}>
                {
                    Array.from({ length: 30 }).map((_, index) => {
                        return <View style={styles.item} key={index}>
                            <Text style={{ fontWeight: 'normal' }}>{index}</Text>
                        </View>
                    })
                }
            </View>
        </View>
    )
}, (prevProps, nextProps) => {
    let arePropsEqual = true;

    arePropsEqual = (prevProps.renderView === nextProps.renderView)
        && (prevProps.renderText === nextProps.renderText)
        && (prevProps.startDay === nextProps.startDay);

    return arePropsEqual;
});



const styles = EfStyleSheet.create({
    container: {
        width: '100%',
        display: 'flex',
        flexDirection: 'column',
    },
    calendarContainer: {
        width: '100%',
        display: 'grid',
        gridTemplateColumns: "1fr 1fr 1fr 1fr 1fr 1fr 1fr",
    },
    item: {
        flex: 1,
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'center'
    }
})
